def validate_iban(value: str) -> str:
    normalized = "".join(value.split()).upper()
    if not 15 <= len(normalized) <= 34:
        raise ValueError("invalid IBAN length")
    if not normalized[:2].isalpha() or not normalized[2:4].isdigit() or not normalized[4:].isalnum():
        raise ValueError("invalid IBAN format")
    rearranged = normalized[4:] + normalized[:4]
    numeric = "".join(str(int(char, 36)) for char in rearranged)
    if int(numeric) % 97 != 1:
        raise ValueError("invalid IBAN checksum")
    return normalized


def validate_bic(value: str) -> str:
    normalized = value.strip().upper()
    if len(normalized) not in {8, 11}:
        raise ValueError("invalid BIC length")
    if not normalized[:4].isalpha() or not normalized[4:6].isalpha() or not normalized[6:8].isalnum():
        raise ValueError("invalid BIC format")
    if len(normalized) == 11 and not normalized[8:].isalnum():
        raise ValueError("invalid BIC branch code")
    return normalized


def luhn_check(pan: str) -> bool:
    digits = [int(char) for char in pan]
    checksum = 0
    parity = len(digits) % 2
    for index, digit in enumerate(digits):
        if index % 2 == parity:
            digit *= 2
            if digit > 9:
                digit -= 9
        checksum += digit
    return checksum % 10 == 0


def decimal_to_minor_units(amount: Decimal) -> int:
