async def verify_merchant_and_terminal(merchant_id: str, terminal_id: str) -> None:
    async with oracle_pool.get_connection() as conn:
        cursor = conn.cursor()
        try:
            cursor.execute(
                """
                SELECT COUNT(1)
                FROM merchant_terminals
                WHERE merchant_id = :merchant_id
                  AND terminal_id = :terminal_id
                """,
                {"merchant_id": merchant_id, "terminal_id": terminal_id},
            )
            row = cursor.fetchone()
            count = int(row[0]) if row else 0
            if count == 0:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Merchant or terminal not found")
        finally:
            cursor.close()


async def ensure_merchant_not_duplicate(request: MerchantOnboardingRequest) -> None:
    async with oracle_pool.get_connection() as conn:
        cursor = conn.cursor()
        try:
            cursor.execute(
                """
                SELECT COUNT(1)
                FROM merchants
                WHERE registration_number = :registration_number
                   OR tax_id = :tax_id
                """,
                {
                    "registration_number": request.registration_number,
                    "tax_id": request.tax_id,
                },
            )
            row = cursor.fetchone()
            count = int(row[0]) if row else 0
            if count > 0:
                raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="Merchant already exists")
        finally:
            cursor.close()


