    expiry_year_full = 2000 + int(request.expiry_year)
    expiry_month_int = int(request.expiry_month)
    current_time = utc_now()
    card_expiry = datetime(expiry_year_full, expiry_month_int, 1, tzinfo=timezone.utc)
    next_month = (card_expiry.replace(day=28) + timedelta(days=4)).replace(day=1)
    if current_time >= next_month:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Card has expired")
    await verify_merchant_and_terminal(request.merchant_id, request.terminal_id)
    transaction_id = generate_reference("TXN")
    amount_minor_units = decimal_to_minor_units(request.amount)
    iso_message = iso8583_processor.create_auth_request(
        pan=request.pan,
        amount=amount_minor_units,
        terminal_id=request.terminal_id,
        merchant_id=request.merchant_id,
        transaction_type=request.transaction_type,
        expiry_month=request.expiry_month,
        expiry_year=request.expiry_year,
        currency=request.currency,
    )
    if not iso_message:
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail="Authorization network unavailable")
    auth_code = generate_reference("AUTH")[-12:]
    ledger_result = ledger_engine.record_card_authorization(
        transaction_id=transaction_id,
        amount=request.amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
        merchant_id=request.merchant_id,
        terminal_id=request.terminal_id,
        currency=request.currency,
        transaction_type=request.transaction_type,
    )
    if not ledger_result:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Ledger recording failed")
    response_code = "00"
