                    "masked_pan": mask_pan(request.pan),
                    "amount": request.amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
                    "currency": request.currency,
                    "transaction_type": request.transaction_type,
                    "auth_code": auth_code,
                    "response_code": response_code,
                },
            )
            conn.commit()
        except HTTPException:
            raise
        except Exception as exc:
            conn.rollback()
            logger.exception("card_authorization_failed", error=str(exc), transaction_id=transaction_id)
            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Card authorization failed") from exc
        finally:
            cursor.close()
    logger.info(
        "card_authorization_approved",
        transaction_id=transaction_id,
        merchant_id=request.merchant_id,
        amount=str(request.amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)),
        transaction_type=request.transaction_type,
    )
    return CardAuthorizationResponse(
        transaction_id=transaction_id,
        status="approved",
        authorization_code=auth_code,
        response_code=response_code,
        amount=request.amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
        currency=request.currency,
    )


@app.get("/api/v1/psd2/accounts", response_model=PSD2AccountsResponse)
async def get_psd2_accounts(authorization: str = Header(..., alias="Authorization")):
    token = extract_bearer_token(authorization)
    original_token = getattr(erste_client, "access_token", None)
    try:
        erste_client.access_token = token
        accounts = await erste_client.get_accounts()
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("psd2_get_accounts_failed", error=str(exc))
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail="Failed to retrieve accounts") from exc
    finally:
        erste_client.access_token = original_token
